-- Guided service catalog foundation: customer-facing needs with educational visual choices.
alter table public.services
  add column if not exists catalog_role text not null default 'customer_service',
  add column if not exists quantity_unit text not null default 'وحدة',
  add column if not exists customer_goal_ar text not null default '';

alter table public.services drop constraint if exists services_catalog_role_check;
alter table public.services
  add constraint services_catalog_role_check check (catalog_role in ('customer_service','component'));

update public.departments
set name_ar='التصميم الفني وصناعة المحتوى والهوية البصرية',
    description_ar='تصميم الهويات والمحتوى والمجلات والبروفايلات والمواد البصرية وتجهيز ملفات الإنتاج.'
where id='dept-design';

insert into public.categories (id,department_id,name_ar,name_en,slug,description_ar,sort_order,is_active)
select x.id,x.department_id,x.name_ar,x.name_en,x.slug,x.description_ar,x.sort_order,x.is_active
from jsonb_to_record('{"id":"cat-content-publications","slug":"content-publications","name_ar":"صناعة المحتوى والمطبوعات التحريرية","name_en":"Content & Editorial Design","is_active":true,"created_at":"2026-10-08T15:03:40.875947+00:00","sort_order":1,"updated_at":"2026-10-08T15:03:40.875947+00:00","department_id":"dept-design","description_ar":"تصميم وصناعة محتوى المجلات والنشرات والبروفايلات والمواد التحريرية."}'::jsonb) as x(
  id text,department_id text,name_ar text,name_en text,slug text,description_ar text,sort_order int,is_active boolean
)
on conflict (id) do update set
  name_ar=excluded.name_ar,name_en=excluded.name_en,slug=excluded.slug,
  description_ar=excluded.description_ar,sort_order=excluded.sort_order,is_active=excluded.is_active;

update public.services set catalog_role='component'
where id = any(array['srv-acp-cladding','srv-channel-letters','srv-flex-lightboxes']);

